SELECT COUNT(*) AS assets, SUM(quantity>0) AS nonzero_assets FROM crypto_ai.wallet_asset;
SELECT id, UNIX_TIMESTAMP(captured_at) AS cap_epoch FROM crypto_ai.wallet_snapshot WHERE captured_at BETWEEN FROM_UNIXTIME(1791741300) AND FROM_UNIXTIME(1791741615) OR captured_at BETWEEN FROM_UNIXTIME(1791747600) AND FROM_UNIXTIME(1791747820) OR captured_at BETWEEN FROM_UNIXTIME(1791765000) AND FROM_UNIXTIME(1791765010) OR captured_at BETWEEN FROM_UNIXTIME(1791778540) AND FROM_UNIXTIME(1791778548) OR captured_at BETWEEN FROM_UNIXTIME(1791788715) AND FROM_UNIXTIME(1791788724) ORDER BY captured_at LIMIT 60;
SELECT id, symbol, side, execution_reason, UNIX_TIMESTAMP(executed_at) AS exec_epoch FROM crypto_ai.wallet_trade WHERE executed_at BETWEEN FROM_UNIXTIME(1791747598) AND FROM_UNIXTIME(1791747840) OR executed_at BETWEEN FROM_UNIXTIME(1791741598) AND FROM_UNIXTIME(1791741612) ORDER BY executed_at LIMIT 40;